    },
    "/v1/players": {
      "get": {
        "operationId": "ref-players",
        "summary": "Search the player directory by name or id",
        "description": "`league` is required and taken as the positional argument — `restish pff players nfl --name\nmahomes`. One row per player: id, name, position, jersey number, current team, college, draft\nrecord, and height and weight in inches and pounds. `--name` is a free-text search and `--id` an\nexact lookup; give one of the two, or the request is refused with `400 invalid_parameter`. Use a row\n`id` as the player positional on any `player-` command.\n\n`name` is forwarded upstream as `q`.",
        "tags": [
          "ref"
        ],
        "x-cli-aliases": [
          "players"
        ],
        "x-requires-one-of": {
          "message": "Give name to search, or id for an exact lookup",
          "alternatives": [
            [
              "name"
            ],
            [
              "id"
            ]
          ]
        },
        "parameters": [
