          },
          "504": {
            "$ref": "#/components/responses/UpstreamTimeout"
          }
        }
      }
    },
    "/v1/teams": {
      "get": {
        "operationId": "team-list",
        "summary": "List a season's teams, franchise groups and schedule",
        "description": "`league` is required and taken as the positional argument — `restish pff team-list nfl --season\n2025`; without `--season` the teams span every era. Three collections in one body: `teams` (the\nseason's franchises with their colours and abbreviations), `franchise_groups` (the conference and\ndivision tree they hang off) and `games` (the season's whole schedule, trimmed to id, both franchise\nids, week and kickoff). Use a `franchise_id` from here as `--franchise` anywhere else, and a game\n`id` as `--game` on any `facet-` command.",
        "tags": [
          "team"
        ],
        "x-cli-aliases": [
          "teams"
        ],
        "parameters": [
          {
            "$ref": "#/components/parameters/league_required"
