          },
          "503": {
            "$ref": "#/components/responses/UpstreamUnavailable"
          },
          "504": {
            "$ref": "#/components/responses/UpstreamTimeout"
          }
        }
      }
    },
    "/v1/teams/overview": {
      "get": {
        "operationId": "team-overview",
        "summary": "Season-to-date team report, one row per team",
        "description": "`league` and `season` are required, and restish takes them as positional arguments in that order —\n`restish pff team-overview nfl 2025`. One row per franchise, totalled over the weeks you ask for;\n`--week` narrows the range and `--franchise` narrows it to one team. Grades are on PFF's 0-100 scale\nand every other column is a raw total or rate; which columns come back depends on the league, the\nquery and the caller's entitlement.",
        "tags": [
          "team"
        ],
        "parameters": [
          {
            "$ref": "#/components/parameters/league_required"
          },
          {
            "$ref": "#/components/parameters/season_required"
          },
          {
            "$ref": "#/components/parameters/week"
          },
          {
            "$ref": "#/components/parameters/franchise_id"
          }
        ],
        "responses": {
          "200": {
            "description": "JSON payload.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/TeamOverviewResponse"
                }
              }
            }
          },
          "400": {
            "$ref": "#/components/responses/BadRequest"
          },
          "401": {
            "$ref": "#/components/responses/Unauthorized"
          },
          "403": {
            "$ref": "#/components/responses/Forbidden"
          },
          "404": {
            "$ref": "#/components/responses/NotFound"
          },
          "429": {
