    "/v1/player/snaps/summary": {
      "get": {
        "operationId": "player-snaps-summary",
        "summary": "Snap counts for a player, broken out by position",
        "description": "`league`, `season` and `player` are required, and restish takes them as positional arguments in that\norder — `restish pff player-snaps-summary nfl 2025 4924`. How many snaps a player took, and where.\n`--week` narrows the counts to one week. This is the one command whose `snap_counts` stays a nested\nobject instead of being flattened into `snap_counts_*` columns.\n\nReturns the raw upstream payload — no report envelope.",
        "tags": [
          "player"
        ],
        "parameters": [
          {
            "$ref": "#/components/parameters/league_required"
          },
          {
            "$ref": "#/components/parameters/season_required"
