	body .promo-message-box {max-width: 1000px;}
	body .sportsbook-offer-msg-box {max-width: none;}

	.info-box {margin: 2em auto;border:1px solid #ccc;padding: 1em;border-left: 4px solid #245fa9;}
	.info-box a {color: #2171cd;font-weight: bold;}
	.info-box .badge-wrapper {margin-bottom:.5em;}
	.info-box .badge-wrapper span {display:inline-block;background: #245fa9;color: #fff;text-transform: uppercase;font-weight:bold;padding: .2em .5em;}


	@media screen and (min-width: 768px) {
		.text-intro {margin-bottom: 4em;}
		.text-intro h1 {font-size: 3em;}
		.text-intro .subhead {font-size: 1.75em;margin-bottom: 1.5em;}

		.main-wrapper h2 {font-size: 2em;}

		.state-units-wrapper {display: grid;margin-bottom: 4em;grid-template-columns: repeat(4, 1fr); grid-gap: 20px;}
		.state {margin:0;}
		.state a {padding-top: 1.5em;padding-bottom: 1.5em;}
		.state-content {display: block;text-align: center;}

		.state .icon {width: 110px; height: 110px;margin-bottom: 15px;margin-right: 0;}
		.state p {font-size: 1.2857142857em;}
		.state .sports-betting {display: block;}

		.homepage-single-blog-wrapper.large-promo-first {
		  grid-template-rows: 1fr 1fr 1fr;
		  grid-template-columns: 57% 1fr; /* use 60% if image isn't as tall */
		  grid-gap: 20px 30px;
		}

		.homepage-single-blog-wrapper.large-promo-first .large-article-promo {
		  grid-row: 1/4;
		}

		.homepage-single-blog-wrapper.large-promo-first .homepage-blog-post a {
		  display: flex;
		  gap: 10px;
		}

		.homepage-single-blog-wrapper.large-promo-first .homepage-blog-post a .image {
		  flex: 1;
		}

		.homepage-single-blog-wrapper.large-promo-first .homepage-blog-post a h3 {
		  flex: 1;
		}

		.picks-wrapper .picks-buttons {grid-template-columns: 1fr 1fr 1fr 1fr;}
		.picks-wrapper .picks-buttons a {padding: .875em;font-size: 1.125rem;}
		/* Tracks the buttons' bump one notch below them, so the flash stays a step
		   smaller than the card it labels at both sizes rather than only one. */
		.picks-new-flash {font-size: 1rem;}

		.info-box {display: flex;gap:1em;align-items: center;}
		.info-box .badge-wrapper {margin-bottom: 0;}
	}

	@media screen and (min-width: 992px) {
		.state-units-wrapper {padding: 0;grid-template-columns: repeat(5, 1fr)}
		.home-nav-section .nav-section-column.double-width {width: min(100%, 490px);}
		.info-box {margin: 3em auto;}
		.info-box a {font-size: 1.125rem;}
	}


	@media screen and (max-width: 991px) {
		.homepage-hero-text {font-size: 34px;width: 700px;bottom: 30px;left: 30px;}
		.homepage-blog-post-wrapper {
		  padding-left: 0;
		  padding-right: 0;
		  margin: 2em auto;
		}
	}
	@media screen and (max-width: 767px) {
		.large-article-promo {max-width: 700px;margin: 3em 8%;}
		.large-article-promo .text {position: static;bottom: auto;padding: 20px;background: #333;}
		.large-article-promo a:hover, .large-article-promo a:focus, .large-article-promo a:active {text-decoration: none;}
		.large-article-promo h2 {font-size: 1.5em;}
		.large-article-promo .see-all {margin: 1em 0; top: 0;}

		.homepage-single-blog-wrapper.large-promo-first {
		  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
		}

		.homepage-blog-post-wrapper.articles-large {gap: 20px;}
