<script data-wp-block-html="js">
document.addEventListener("DOMContentLoaded", function () {

  const nav = document.querySelector(".wtr-nav");

  if (!nav) return;

  const mobileToggle =
    nav.querySelector(".wtr-mobile-toggle");

  const dropdowns =
    nav.querySelectorAll(".wtr-has-menu");

  const dropdownButtons =
    nav.querySelectorAll(".wtr-top-link");


  /* ---------------------------------------
     Close all dropdowns
     --------------------------------------- */

  function closeAll(except = null) {

    dropdowns.forEach(function (item) {

      if (item === except) return;

      item.classList.remove("wtr-open");

      const button =
        item.querySelector(".wtr-top-link");

      if (button) {
        button.setAttribute(
          "aria-expanded",
          "false"
        );
      }

    });

  }


  /* ---------------------------------------
     Desktop/mobile dropdown clicks
     --------------------------------------- */

  dropdownButtons.forEach(function (button) {

    button.addEventListener(
      "click",
      function (event) {

        event.preventDefault();

        const parent =
          button.closest(".wtr-has-menu");

        const isOpen =
          parent.classList.contains("wtr-open");

        closeAll(parent);

        parent.classList.toggle(
          "wtr-open",
          !isOpen
        );

        button.setAttribute(
          "aria-expanded",
          String(!isOpen)
        );

      }
    );

  });


  /* ---------------------------------------
     Mobile hamburger
     --------------------------------------- */

  if (mobileToggle) {

    mobileToggle.addEventListener(
      "click",
      function () {

        const isOpen =
          nav.classList.contains(
            "wtr-mobile-open"
          );

        nav.classList.toggle(
          "wtr-mobile-open",
          !isOpen
        );

        mobileToggle.setAttribute(
          "aria-expanded",
          String(!isOpen)
        );

        if (isOpen) {
          closeAll();
        }

      }
    );

  }


  /* ---------------------------------------
     Close when clicking outside
     --------------------------------------- */

  document.addEventListener(
    "click",
    function (event) {

      if (!nav.contains(event.target)) {

        closeAll();

        nav.classList.remove(
          "wtr-mobile-open"
        );

        if (mobileToggle) {
          mobileToggle.setAttribute(
            "aria-expanded",
            "false"
          );
        }

      }

    }
  );


  /* ---------------------------------------
     Escape key closes menu
     --------------------------------------- */

  document.addEventListener(
    "keydown",
    function (event) {

      if (event.key === "Escape") {

        closeAll();

        nav.classList.remove(
          "wtr-mobile-open"
        );

        if (mobileToggle) {
          mobileToggle.setAttribute(
            "aria-expanded",
            "false"
          );
        }

      }

    }
  );


  /* ---------------------------------------
     Reset when moving desktop/mobile
     --------------------------------------- */

  window.addEventListener(
    "resize",
    function () {

      if (window.innerWidth > 900) {

        nav.classList.remove(
          "wtr-mobile-open"
        );

        if (mobileToggle) {
          mobileToggle.setAttribute(
            "aria-expanded",
            "false"
          );
        }

      }

    }
  );

});
</script>

