        .mform-head a{font-family:var(--mono);font-size:11px;color:var(--ink-dim);letter-spacing:.05em;text-transform:uppercase;white-space:nowrap;}
        .mform-head a:hover{color:var(--action-hi);}

        /* ============================================================
           HERO — pick card (left) + performance card (right), equal height
           ============================================================ */
        .hero{padding:26px 0 0;}
        .hero-grid{display:grid;grid-template-columns:1fr;gap:20px;max-width:520px;margin:0 auto;}
        .hero-l,.hero-r{display:flex;flex-direction:column;gap:16px;min-width:0;}

        /* hero pick card */
        .obcard{position:relative;overflow:hidden;padding:24px 22px 22px;display:flex;flex-direction:column;}
        .obcard::before{content:"";position:absolute;left:0;right:0;top:0;height:2px;background:linear-gradient(90deg,transparent,var(--action),transparent);}
        .obkick{font-family:var(--mono);font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:var(--ink-dim);display:inline-flex;align-items:center;gap:8px;}
        .obkick i{color:var(--action-hi);}
        .obcard h1.obh{font-size:1.05rem;font-weight:700;color:var(--ink);letter-spacing:-.02em;line-height:1.2;margin:14px 0 0;}
        .obcrests{display:flex;align-items:center;gap:10px;margin:12px 0 2px;}
        .obcrests img{width:34px;height:34px;object-fit:contain;}
        .obcrests img.obface{width:44px;height:44px;border-radius:50%;object-fit:cover;object-position:top;background:var(--panel-2);border:1px solid var(--line);}
        .obcrests .obv{font-family:var(--mono);font-size:.66rem;color:var(--ink-faint);text-transform:uppercase;}
        .obpick{font-size:clamp(2rem,5vw,2.5rem);font-weight:800;letter-spacing:-.04em;line-height:1.03;color:var(--ink);margin-top:6px;overflow-wrap:anywhere;}
        .obpick .grad{color:var(--action-hi);}
        .obwhy{color:var(--ink-dim);font-size:15px;margin:13px 0 0;line-height:1.5;max-width:34ch;}

        /* conviction dots */
        .obconv{display:flex;align-items:center;gap:11px;margin-top:20px;}
        .obconv .dots{display:flex;gap:5px;}
        .obconv .dots i{width:7px;height:7px;border-radius:50%;background:var(--model);}
        .obconv .dots i.off{background:var(--line-strong);}
        .obconv .lab{font-size:14.5px;font-weight:700;letter-spacing:-.01em;color:var(--ink);}
        .obconv .lab .sub{font-family:var(--mono);font-size:10.5px;font-weight:400;color:var(--ink-faint);text-transform:uppercase;letter-spacing:.1em;margin-left:6px;}

        /* odds readout */
        .oddsrow{display:flex;margin-top:20px;border-top:1px solid var(--line-strong);}
        .oddsrow div{padding:14px 0 2px;flex:1;min-width:0;}
        .oddsrow div+div{border-left:1px solid var(--line);padding-left:16px;}
        .oddsrow .k{font-family:var(--mono);font-size:10px;letter-spacing:.09em;text-transform:uppercase;color:var(--ink-faint);display:block;margin-bottom:5px;}
        .oddsrow .v{font-family:var(--mono);font-size:15px;font-weight:700;color:var(--ink);}
        .oddsrow .v.b{color:var(--action-hi);}

        /* hero CTA row: buttons EQUAL height + width */
        .hero-cta{margin-top:20px;}
        .hero-cta > div{display:flex;gap:10px;flex-wrap:wrap;}
        .hero-cta .btn-grad,.hero-cta .btn-glass,.hero-cta .btn-neon{flex:1 1 150px;min-height:50px;display:inline-flex;align-items:center;justify-content:center;gap:9px;margin:0;box-sizing:border-box;font-size:.95rem;}
        .hero-note{font-family:var(--mono);font-size:.72rem;color:var(--ink-faint);margin-top:14px;display:flex;align-items:center;gap:8px;}
        .hero-note i{color:var(--action-hi);}
        .obseal{display:flex;gap:11px;align-items:flex-start;margin-top:16px;padding-top:16px;border-top:1px solid var(--line);}
        .obseal svg{color:var(--model);flex:none;margin-top:1px;}
        .obseal p{font-size:12.5px;color:var(--ink-dim);line-height:1.5;margin:0;}
        .obseal b{color:var(--ink);font-weight:650;}

        /* members proof bar */
        .members2{display:flex;align-items:center;gap:12px;padding:13px 16px;}
        .members2 .faces{display:flex;}
        .members2 .faces span{width:26px;height:26px;border-radius:50%;border:2px solid var(--panel);margin-left:-8px;background:linear-gradient(145deg,var(--accent-2),var(--action));}
        .members2 .faces span:first-child{margin-left:0;}
        .members2 p{font-size:13.5px;color:var(--ink-dim);margin:0;}
        .members2 b{color:var(--ink);font-weight:700;}

        /* performance card (Option-3: form + windows + result rows) */
        .mform{padding:6px 20px 18px;display:flex;flex-direction:column;}
        .mtop

{display:flex;align-items:flex-end;justify-content:space-between;gap:12px;padding:16px 0 15px;}
        .mtop .big{font-size:1.5rem;font-weight:780;letter-spacing:-.03em;color:var(--ink);line-height:1.1;}
        .mtop .big em{color:var(--model);font-style:normal;}
        .mtop .rate{text-align:right;font-family:var(--mono);flex:none;}
        .mtop .rate .n{font-size:1.3rem;font-weight:700;color:var(--ink);}
        .mtop .rate .k{font-size:9.5px;color:var(--ink-faint);text-transform:uppercase;letter-spacing:.1em;margin-top:2px;}
        .mframes{display:flex;border-top:1px solid var(--line);}
        .mframes .fr{flex:1;padding:14px 0 15px;text-align:center;}
        .mframes .fr+.fr{border-left:1px solid var(--line);}
        .mframes .fr .k{font-family:var(--mono);font-size:9px;letter-spacing:.11em;text-transform:uppercase;color:var(--ink-faint);display:block;margin-bottom:7px;}
        .mframes .fr .v{font-family:var(--mono);font-size:15px;font-weight:700;color:var(--model);}
        .mframes .fr .v.pos{color:var(--model);}
        .mframes .fr .v.neg{color:var(--book);}
        /* recent result rows (server-built .brow) */
        .brow{display:flex;align-items:center;gap:12px;padding:11px 0;border-top:1px solid var(--line);}
        .brow .rlogo{width:30px;height:30px;object-fit:contain;flex:none;border-radius:8px;background:var(--panel);box-shadow:inset 0 0 0 1px var(--line-strong);}
        /* [2026-08-01] Athlete headshots in this strip. .brow .rlogo is more specific than the
           shared img.bb-face, so the crop has to be restated or a face letterboxes inside the puck.
           Border-radius is deliberately NOT overridden: face, team logo and initials chip all keep
           the strip's 8px puck, so the rows stay visually uniform. */
        .brow img.rlogo.bb-face{object-fit:cover;}
        .brow .bt{flex:1;min-width:0;}
        .brow .bt .bh{font-size:14px;font-weight:600;letter-spacing:-.01em;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
        .brow .bt .bm{font-family:var(--mono);font-size:10.5px;color:var(--ink-faint);margin-top:2px;}
        .brow .out{display:flex;align-items:center;gap:9px;flex:none;}
        .brow .out .bp{font-family:var(--mono);font-size:13.5px;font-weight:700;font-variant-numeric:tabular-nums;}
        .brow.w .out .bp{color:var(--model);}
        .brow.l .out .bp{color:var(--book);}
        .brow .bic{width:21px;height:21px;border-radius:50%;display:grid;place-items:center;flex:none;}
        .brow.w .bic{background:var(--model-dim);color:var(--model);}
        .brow.l .bic{background:var(--book-dim);color:var(--book);}
        .brow .bic svg{width:11px;height:11px;}
        .mcov{margin-top:auto;padding:14px 0 2px;border-top:1px solid var(--line);text-align:center;font-family:var(--mono);font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:var(--ink-faint);line-height:1.9;}
        .mcov b{color:var(--ink-dim);font-weight:500;}

        /* ============================================================
           A FEW MORE WE LIKE — pick cards + unlock
           ============================================================ */
        .picks{display:flex;flex-direction:column;gap:11px;}
        /* [2026-08-21] hub-slate idiom for "a few more we like" (same anatomy as the picks hubs;
           tokens only, so light theme flips with the master). Old .pk styles kept below for safety. */
        .hub-card{background:var(--panel);border:1px solid var(--card-edge);border-radius:16px;box-shadow:var(--shadow-card);overflow:hidden;}
        .hub-slate table{width:100%;border-collapse:collapse;}
        .hub-slate td{padding:11px 16px;border-top:1px solid var(--line);vertical-align:middle;}
        .hub-slate tr:first-child td{border-top:0;}
        .hub-g{font-family:var(--mono);font-size:.72rem;color:var(--ink-faint);}
        .hub-g img{width:20px;height:20px;object-fit:contain;vertical-align:middle;margin:0 2px;}
        .hub-sel{font-size:.92rem;font-weight:600;color:var(--ink);}
        .hub-pr{text-align:right;font-weight:700;font-variant-numeric:tabular-nums;white-space:nowrap;color:var(--ink);}
        .hub-cf{font-family:var(--mono);font-size:.62rem;letter-spacing:.05em;text-transform:uppercase;text-align:right;white-space:nowrap;}
        .hub-c-high{color:var(--model);} .hub-c-lean{color:var(--gold);} .hub-c-long{color:var(--ink-faint);}
        .hub-ch{display:block;margin-top:2px;font-size:.6rem;letter-spacing:.03em;text-transform:none;color:var(--ink-dim);font-variant-numeric:tabular-nums;}
        .hub-lockbar{display:inline-block;height:9px;width:100px;border-radius:3px;opacity:.5;background:repeating-linear-gradient(90deg,var(--line-strong) 0 20px,var(--line) 20px 32px);}
        .hub-legend{padding:9px 16px;border-top:1px solid var(--line);font-family:var(--mono);font-size:.62rem;letter-spacing:.04em;color:var(--ink-faint);}
        @media(max-width:560px){.hub-slate td{padding:10px 9px;}.hub-sel{font-size:.85rem;}.hub-lockbar{width:56px;}.hub-g{white-space:normal;font-size:.66rem;}.hub-g img{width:16px;height:16px;}}
        /* [2026-08-21] what's-on-tonight league cards + latest-from-the-desk article cards */
        .lgstrip{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px;}
        .lgx{display:flex;align-items:center;gap:10px;padding:11px 13px;border-radius:12px;text-decoration:none;transition:transform .15s ease,border-color .15s ease;}
        .lgx:hover{border-color:var(--action);transform:translateY(-1px);}
        .lgx img{width:22px;height:22px;object-fit:contain;flex:none;}
        .lgx .nm{font-weight:700;font-size:.88rem;color:var(--ink);}
        .lgx .ct{margin-left:auto;font-family:var(--mono);font-size:.66rem;color:var(--model);white-space:nowrap;}
        .deskstrip{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:10px;}
        .desk{display:flex;flex-direction:column;text-decoration:none;overflow:hidden;border-radius:14px;transition:transform .15s ease,border-color .15s ease;}
        .desk:hover{border-color:var(--action);transform:translateY(-1px);}
        .desk-th{display:block;height:96px;background-size:cover;background-position:center;border-bottom:1px solid var(--line);}
        .desk-vs{display:flex;align-items:center;justify-content:center;gap:14px;padding:18px 0 14px;border-bottom:1px solid var(--line);background:var(--panel-2);}
        .desk-vs img{width:40px;height:40px;object-fit:contain;}
        .desk-x{font-family:var(--mono);font-size:.66rem;color:var(--ink-faint);text-transform:uppercase;}
        .desk-in{display:block;padding:12px 14px;}
        .desk-k{display:block;font-family:var(--mono);font-size:.62rem;letter-spacing:.08em;text-transform:uppercase;color:var(--model);margin-bottom:6px;}
        .desk-h{display:block;font-weight:650;font-size:.9rem;line-height:1.35;color:var(--ink);}
        .pk{display:flex;align-items:center;gap:14px;padding:16px 17px;}
        .pk .pkt{flex:1;min-width:0;}
        .pk .pkh{font-size:16px;font-weight:640;letter-spacing:-.01em;color:var(--ink);}
        .pk .pkm{font-family:var(--mono);font-size:11.5px;color:var(--ink-faint);margin-top:4px;}
        .lean{display:inline-flex;align-items:center;gap:7px;font-size:12.5px;font-weight:600;letter-spacing:-.01em;white-space:nowrap;flex:none;}
        .lean::before{content:"";width:7px;height:7px;border-radius:50%;background:currentColor;}
        .lean.s{color:var(--model);}
        .lean.w{color:var(--action-hi);}
        /* locked/blurred teaser — the actual pick is withheld server-side for non-subscribers */
        .pk.locked{cursor:pointer;}
        .pk.locked .pkbar{height:15px;width:58%;border-radius:6px;background:linear-gradient(90deg,var(--ink-faint),var(--line-strong),var(--ink-faint));filter:blur(3.5px);opacity:.65;}
        .pk.locked .pkm{margin-top:9px;}
        .pk .pklk{flex:none;width:30px;height:30px;border-radius:9px;display:grid;place-items:center;color:var(--gold);background:rgba(245,179,1,.12);border:1px solid rgba(245,179,1,.3);}
        .pk.locked:hover{border-color:rgba(245,179,1,.4);}
        .unlock2{display:flex;align-items:center;gap:13px;padding:17px;border:1px solid rgba(245,179,1,.35);border-radius:16px;background:linear-gradient(180deg,rgba(245,179,1,.07),transparent);cursor:pointer;text-decoration:none;}
        .unlock2 .ulock{width:38px;height:38px;border-radius:11px;background:rgba(245,179,1,.13);border:1px solid rgba(245,179,1,.3);display:grid;place-items:center;color:var(--gold);flex:none;}
        .unlock2 .ut{flex:1;min-width:0;}
        .unlock2 .uh{font-size:15.5px;font-weight:680;color:var(--ink);display:block;}
        .unlock2 .um{font-size:12.5px;color:var(--ink-dim);margin-top:2px;display:block;}
        .unlock2 .ugo{font-family:var(--mono);font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--gold);flex:none;}

        /* ============================================================
           TRUST ROW
           ============================================================ */
        .trust{margin:6px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);}
        .trust .wrap{display:flex;flex-wrap:wrap;gap:12px 28px;justify-content:center;padding:18px 0;}
        .trust .t{display:inline-flex;align-items:center;gap:9px;font-size:.86rem;color:var(--ink-dim);}
        .trust .t i{color:var(--action-hi);}
        .trust .t b{color:var(--ink);font-weight:600;}

        /* ============================================================
           LIVE BOARD — game cards (3-up desktop, equal height)
           ============================================================ */
        .board-head{display:flex;justify-content:space-between;align-items:flex-end;flex-wrap:wrap;gap:16px;margin-bottom:22px;}
        .board-grid{display:grid;grid-template-columns:1fr;gap:12px;}
        .gcard{position:relative;display:flex;flex-direction:column;gap:14px;padding:20px;background:linear-gradient(180deg,var(--panel-2),var(--panel));border:1px solid var(--card-edge);border-radius:14px;box-shadow:var(--shadow-card);transition:transform .18s,border-color .18s;overflow:hidden;}
        .gcard:hover,.gcard:focus-visible{border-color:var(--accent-1);transform:translateY(-3px);}
        .gc-top{display:flex;justify-content:space-between;align-items:center;gap:8px;font-family:var(--mono);font-size:.7rem;color:var(--ink-faint);}
        .gc-top .gc-time{color:var(--ink-dim);}
        .gteam{display:flex;justify-content:space-between;align-items:center;gap:8px;}
        .gteam .nm{display:flex;align-items:center;gap:10px;font-weight:600;color:var(--ink);font-size:.96rem;min-width:0;}
        .gteam .nm img{width:26px;height:26px;object-fit:contain;flex:none;}
        /* [2026-07-30] Logo-less sides (cricket, some WNBA expansion teams) keep the 26px slot so
           HOME/AWAY rows stay aligned, showing the team's own initials instead of a hole.
           [2026-08-01] The .tlogo-ph rule that used to sit here was DELETED, not moved: the chip is
           now defined once in the Site.Master style block, de-scoped, with .bb-ph-26 supplying the
           same 26px circle. Keeping a copy here would let the two drift.
           This one rule stays because it is an override, not a duplicate — .gteam .nm img above is
           more specific than the shared img.bb-face, so without it a tennis/UFC headshot would be
           letterboxed by object-fit:contain instead of filling the circle. */
        .gteam .nm img.bb-face{object-fit:cover;}
        /* Full team names are longer than 3-letter codes — let them wrap rather than overflow. */
        .gteam .nm{overflow-wrap:anywhere

;}
        .gteam .pos{font-family:var(--mono);font-size:.64rem;color:var(--ink-faint);flex:none;}
        .gc-foot{margin-top:auto;border-top:1px solid var(--line);padding-top:14px;display:flex;justify-content:space-between;align-items:center;gap:8px;}
        .gc-foot .view{font-family:var(--mono);font-size:.74rem;color:var(--ink-dim);}
        .lock{font-family:var(--mono);font-size:.66rem;font-weight:700;padding:4px 9px;border-radius:6px;display:inline-flex;align-items:center;gap:5px;flex:none;}
        .lock.pro{color:var(--action);background:rgba(59,130,246,.1);border:1px solid rgba(59,130,246,.28);}
        .lock.free{color:var(--action-hi);background:rgba(59,130,246,.1);border:1px solid rgba(59,130,246,.28);}

        /* ============================================================
           WHY IT WORKS (3-up desktop) · QUOTES (2-up desktop)
           ============================================================ */
        .whys{display:flex;flex-direction:column;gap:11px;}
        .why-i{display:flex;gap:15px;padding:18px;}
        .why-i .n{font-family:var(--mono);font-size:12px;font-weight:700;color:var(--action-hi);border:1px solid var(--card-edge);border-radius:9px;width:34px;height:34px;display:grid;place-items:center;flex:none;}
        .why-i .h{font-size:15.5px;font-weight:680;letter-spacing:-.01em;color:var(--ink);}
        .why-i .p{font-size:14px;color:var(--ink-dim);margin:5px 0 0;line-height:1.5;}
        .quotes{display:flex;flex-direction:column;gap:11px;}
        .q{padding:18px;}
        .q p{font-size:15.5px;line-height:1.5;letter-spacing:-.01em;color:var(--ink);margin:0;}
        .q .by{display:block;font-family:var(--mono);font-size:11.5px;color:var(--ink-faint);margin-top:11px;}

        /* ============================================================
           PRICING — plan cards (3-up desktop, equal height, buttons pinned)
           ============================================================ */
        .pricing-section{padding:38px 0;}
        .pgrid{display:grid;grid-template-columns:1fr;gap:14px;max-width:1040px;margin:0 auto;}
        .pcard{padding:28px;display:flex;flex-direction:column;position:relative;}
        .pcard.featured{border-color:var(--action);box-shadow:0 0 0 1px var(--action),var(--shadow-card);}
        .pcard.featured::before{content:"MOST CHOSEN";position:absolute;top:-11px;left:50%;transform:translateX(-50%);background:var(--action);color:#fff;font-family:var(--mono);font-size:.62rem;font-weight:700;letter-spacing:.06em;padding:4px 12px;border-radius:99px;white-space:nowrap;}
        .pcard h3{font-family:var(--display);color:var(--ink);font-size:1.3rem;margin:0;}
        .pcard .price{font-family:var(--mono);font-weight:700;font-size:2.3rem;color:var(--ink);margin:14px 0 16px;font-variant-numeric:tabular-nums;line-height:1;}
        .pcard .price small{font-family:var(--ui);font-size:.9rem;color:var(--ink-faint);font-weight:400;}
        .pcard ul{display:flex;flex-direction:column;gap:11px;margin:0 0 24px;padding:0;list-style:none;}
        .pcard li{display:flex;gap:10px;color:var(--ink-dim);font-size:.9rem;line-height:1.45;}
        .pcard li i{color:var(--action-hi);margin-top:3px;}
        .pcard .btn-neon,.pcard .btn-glass{width:100%;margin-top:auto;}
        .price-reassure{text-align:center;font-family:var(--mono);font-size:.78rem;color:var(--ink-faint);margin-top:22px;}
        .price-reassure i{color:var(--action-hi);margin:0 4px 0 14px;}
        .price-reassure i:first-child{margin-left:0;}

        /* ============================================================
           FAQ (matches JSON-LD) · RESPONSIBLE GAMBLING · STICKY CTA
           ============================================================ */
        .faq{max-width:780px;margin:0 auto;}
        .faq details{border-bottom:1px solid var(--line);padding:20px 0;}
        .faq summary{font-family:var(--ui);font-weight:600;color:var(--ink);cursor:pointer;list-style:none;display:flex;justify-content:space-between;gap:16px;font-size:1.02rem;}
        .faq summary::-webkit-details-marker{display:none;}
        .faq summary::after{content:"+";color:var(--action);font-family:var(--mono);font-weight:700;}
        .faq details[open] summary::after{content:"–";}
        .faq details p{color:var(--ink-dim);margin:14px 0 0;line-height:1.62;font-size:.95rem;}

        .rg-band{margin-top:8px;background:var(--rail-bg);border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:28px 0;text-align:center;}
        .rg-band .pill{font-family:var(--mono);font-size:.7rem;color:var(--ink);border:1px solid var(--line-strong);border-radius:99px;padding:4px 12px;letter-spacing:.06em;display:inline-block;margin-bottom:14px;}
        .rg-band p{color:var(--ink-dim);font-size:.88rem;line-height:1.62;max-width:760px;margin:0 auto;}
        .rg-band b{color:var(--ink);}
        .rg-band a{color:var(--ink);border-bottom:1px solid var(--line-strong);}
        .rg-band a:hover{color:var(--action-hi);}

        .disclaimer{margin-top:24px;background:rgba(245,179,1,.05);border:1px solid rgba(245,179,1,.22);border-radius:12px;padding:16px 20px;color:var(--ink-dim);font-size:.85rem;line-height:1.55;text-align:center;}
        .disclaimer b{color:var(--gold);}

        .sticky-bar{position:fixed;bottom:20px;left:50%;transform:translateX(-50%) translateY(200%);background:var(--accent-grad);color:#fff;padding:13px 30px;border-radius:99px;box-shadow:0 10px 28px -6px var(--accent-glow);z-index:8000;font-weight:700;transition:.3s cubic-bezier(.175,.885,.32,1.275);white-space:nowrap;font-family:var(--ui);}
        .sticky-bar.visible{transform:translateX(-50%) translateY(0);}

        /* ============================================================
           RESPONSIVE
           mobile (<900px): single centered column ~520px
           desktop (>=900px): ~1120px page, 2-col hero, gridded sections
           ============================================================ */
        @media(max-width:899px){
          .icp-page{max-width:520px;}
          .board-grid,.pgrid,.whys,.quotes{grid-template-columns:1fr;}
        }
        @media(min-width:900px){
          .hero-grid{grid-template-columns:1.02fr .98fr;gap:28px;max-width:100%;align-items:stretch;}
          .hero-l>.obcard{flex:1;}
          .hero-r>.mform{flex:1;}
          .secwrap{max-width:820px;}
          .whys{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;}
          .quotes{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;}
          .picks{max-width:620px;margin:0 auto;}
          .pgrid{grid-template-columns:repeat(3,1fr);gap:14px;align-items:stretch;}
          .board-grid{grid-template-columns:repeat(3,1fr);gap:12px;}
        }

        @media(prefers-reduced-motion:reduce){.gcard:hover{transform:none;}}
