    lic=(j.get("license") or {}).get("spdx_id","?")
    print(f"{fn:42} {d['status']} stars:{j.get('stargazers_count','?')} lic:{lic} push:{str(j.get('pushed_at',''))[:10]} desc:{str(j.get('description',''))[:70]}")
